'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'
import AuthForm from './components/AuthForm'
import Wallet from './components/Wallet'
import MatchCard from './components/MatchCard'
import PredictionModal from './components/PredictionModal'
import Leaderboard from './components/Leaderboard'
import { Match } from '@/lib/types'

export default function Home() {
  const [user, setUser] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [matches, setMatches] = useState<Match[]>([])
  const [wallet, setWallet] = useState<any>(null)
  const [selectedMatch, setSelectedMatch] = useState<Match | null>(null)
  const [activeTab, setActiveTab] = useState<'matches' | 'leaderboard'>('matches')

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null)
      setLoading(false)
    })

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null)
    })

    return () => subscription.unsubscribe()
  }, [])

  useEffect(() => {
    if (user) {
      fetchMatches()
      fetchWallet()
    }
  }, [user])

  const fetchMatches = async () => {
    const { data } = await supabase
      .from('matches')
      .select('*')
      .order('match_date', { ascending: true })
    
    if (data) setMatches(data)
  }

  const fetchWallet = async () => {
    const { data } = await supabase
      .from('wallet')
      .select('*')
      .eq('user_id', user.id)
      .single()
    
    if (data) setWallet(data)
  }

  const handleLogout = async () => {
    await supabase.auth.signOut()
  }

  const handlePredictionSuccess = () => {
    fetchWallet()
    setSelectedMatch(null)
  }

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-blue-50 to-green-50">
        <div className="text-2xl">⏳ Loading...</div>
      </div>
    )
  }

  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-green-50 py-12 px-4">
        <AuthForm />
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-green-50">
      {/* Header */}
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-3">
              <span className="text-3xl">🏏</span>
              <div>
                <h1 className="text-2xl font-bold text-gray-800">PSL Predictions</h1>
                <p className="text-sm text-gray-600">{user.email}</p>
              </div>
            </div>
            <button
              onClick={handleLogout}
              className="px-4 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600 transition text-sm"
            >
              🚪 Logout
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Wallet */}
        <div className="mb-8">
          <Wallet userId={user.id} />
        </div>

        {/* Tabs */}
        <div className="flex gap-2 mb-6">
          <button
            onClick={() => setActiveTab('matches')}
            className={`px-6 py-3 rounded-lg font-semibold transition ${
              activeTab === 'matches'
                ? 'bg-white text-blue-600 shadow-md'
                : 'bg-white/50 text-gray-600 hover:bg-white'
            }`}
          >
            🏏 Live Matches
          </button>
          <button
            onClick={() => setActiveTab('leaderboard')}
            className={`px-6 py-3 rounded-lg font-semibold transition ${
              activeTab === 'leaderboard'
                ? 'bg-white text-blue-600 shadow-md'
                : 'bg-white/50 text-gray-600 hover:bg-white'
            }`}
          >
            🏆 Leaderboard
          </button>
        </div>

        {/* Content */}
        {activeTab === 'matches' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {matches.map((match) => (
              <MatchCard
                key={match.id}
                match={match}
                onPredict={setSelectedMatch}
              />
            ))}
            
            {matches.length === 0 && (
              <div className="col-span-full text-center py-16 text-gray-400">
                <p className="text-xl font-semibold">No matches available</p>
                <p className="text-sm mt-2">Check back soon for PSL matches!</p>
              </div>
            )}
          </div>
        ) : (
          <Leaderboard />
        )}
      </div>

      {/* Prediction Modal */}
      {selectedMatch && wallet && (
        <PredictionModal
          match={selectedMatch}
          userId={user.id}
          currentCredits={wallet.credits_balance}
          onClose={() => setSelectedMatch(null)}
          onSuccess={handlePredictionSuccess}
        />
      )}
    </div>
  )
}
