'use client'

import { useState } from 'react'
import { supabase } from '@/lib/supabase'
import { Match } from '@/lib/types'

interface PredictionModalProps {
  match: Match
  userId: string
  currentCredits: number
  onClose: () => void
  onSuccess: () => void
}

export default function PredictionModal({ 
  match, 
  userId, 
  currentCredits,
  onClose, 
  onSuccess 
}: PredictionModalProps) {
  const [selectedAction, setSelectedAction] = useState<string | null>(null)
  const [prediction, setPrediction] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')

  const actions = [
    {
      id: 'over_outcome',
      name: '🎯 Over Outcome',
      description: 'Predict runs in next over',
      cost: 2,
      winAmount: 5,
      options: [
        { value: '0-6', label: '0-6 Runs (Tight)' },
        { value: '7-12', label: '7-12 Runs (Normal)' },
        { value: '13+', label: '13+ Runs (Big Over)' }
      ]
    },
    {
      id: 'boundary_rush',
      name: '⚡ Boundary Rush',
      description: 'Boundary in next 3 balls?',
      cost: 1,
      winAmount: 3,
      options: [
        { value: 'yes', label: '✅ Yes, Boundary Coming' },
        { value: 'no', label: '❌ No Boundary' }
      ]
    },
    {
      id: 'wicket_window',
      name: '🎲 Wicket Window',
      description: 'Wicket in next 2 overs?',
      cost: 1,
      winAmount: 4,
      options: [
        { value: 'yes', label: '✅ Yes, Wicket Falls' },
        { value: 'no', label: '❌ No Wicket' }
      ]
    }
  ]

  const selectedActionData = actions.find(a => a.id === selectedAction)

  const handleSubmit = async () => {
    if (!selectedAction || !prediction) {
      setMessage('⚠️ Please select an option')
      return
    }

    if (currentCredits < (selectedActionData?.cost || 0)) {
      setMessage('❌ Not enough credits!')
      return
    }

    setLoading(true)
    setMessage('')

    try {
      // Get current wallet data first
      const { data: walletData } = await supabase
        .from('wallet')
        .select('*')
        .eq('user_id', userId)
        .single()

      if (!walletData) {
        throw new Error('Wallet not found')
      }

      // Calculate new values
      const newBalance = walletData.credits_balance - (selectedActionData?.cost || 0)
      const newTotalPredictions = walletData.total_predictions + 1

      // Update wallet
      const { error: walletError } = await supabase
        .from('wallet')
        .update({ 
          credits_balance: newBalance,
          total_predictions: newTotalPredictions
        })
        .eq('user_id', userId)

      if (walletError) throw walletError

      // Create prediction
      const { error: predError } = await supabase
        .from('predictions')
        .insert({
          user_id: userId,
          match_id: match.id,
          action_type: selectedAction,
          prediction_data: { prediction, match_state: match.current_over },
          credits_spent: selectedActionData?.cost || 0
        })

      if (predError) throw predError

      setMessage('✅ Prediction placed successfully!')
      setTimeout(() => {
        onSuccess()
        onClose()
      }, 1000)

    } catch (error: any) {
      setMessage('❌ ' + error.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-2xl max-w-lg w-full max-h-[90vh] overflow-y-auto">
        <div className="sticky top-0 bg-gradient-to-r from-blue-600 to-purple-600 text-white p-6 rounded-t-2xl">
          <div className="flex justify-between items-start">
            <div>
              <h2 className="text-2xl font-bold">🎯 Make Your Play</h2>
              <p className="text-sm opacity-90 mt-1">{match.team_a} vs {match.team_b}</p>
              <p className="text-xs opacity-75 mt-1">Over: {match.current_over}</p>
            </div>
            <button onClick={onClose} className="text-2xl hover:bg-white/20 rounded-lg px-3 py-1">×</button>
          </div>
          <div className="mt-3 flex items-center gap-2 bg-white/20 rounded-lg px-4 py-2">
            <span className="text-sm">Your Credits:</span>
            <span className="text-xl font-bold">{currentCredits}</span>
          </div>
        </div>

        <div className="p-6">
          {!selectedAction ? (
            <div className="space-y-3">
              <h3 className="font-semibold text-gray-700 mb-4">Choose Your Action:</h3>
              {actions.map((action) => (
                <button
                  key={action.id}
                  onClick={() => setSelectedAction(action.id)}
                  className="w-full text-left p-4 border-2 border-gray-200 rounded-xl hover:border-blue-500 hover:shadow-md transition"
                >
                  <div className="flex justify-between items-start">
                    <div>
                      <p className="font-bold text-gray-800">{action.name}</p>
                      <p className="text-sm text-gray-600 mt-1">{action.description}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-xs text-gray-500">Cost</p>
                      <p className="text-lg font-bold text-blue-600">{action.cost}</p>
                    </div>
                  </div>
                  <div className="mt-2 text-xs text-green-600 font-semibold">
                    Win: {action.winAmount} credits
                  </div>
                </button>
              ))}
            </div>
          ) : (
            <div className="space-y-4">
              <button
                onClick={() => {
                  setSelectedAction(null)
                  setPrediction(null)
                }}
                className="text-sm text-blue-600 hover:underline"
              >
                ← Back to actions
              </button>

              <div className="bg-blue-50 border-2 border-blue-200 rounded-xl p-4">
                <h3 className="font-bold text-gray-800">{selectedActionData?.name}</h3>
                <p className="text-sm text-gray-600 mt-1">{selectedActionData?.description}</p>
                <div className="flex justify-between mt-3 text-sm">
                  <span className="text-gray-600">Cost: <span className="font-bold text-blue-600">{selectedActionData?.cost} credits</span></span>
                  <span className="text-gray-600">Win: <span className="font-bold text-green-600">{selectedActionData?.winAmount} credits</span></span>
                </div>
              </div>

              <div className="space-y-2">
                <h4 className="font-semibold text-gray-700">Your Prediction:</h4>
                {selectedActionData?.options.map((option) => (
                  <button
                    key={option.value}
                    onClick={() => setPrediction(option.value)}
                    className={`w-full p-4 rounded-xl border-2 transition ${
                      prediction === option.value
                        ? 'border-blue-600 bg-blue-50 shadow-md'
                        : 'border-gray-200 hover:border-blue-300'
                    }`}
                  >
                    <span className="font-semibold text-gray-800">{option.label}</span>
                  </button>
                ))}
              </div>

              {message && (
                <div className={`p-3 rounded-lg text-sm ${
                  message.includes('✅') ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                }`}>
                  {message}
                </div>
              )}

              <button
                onClick={handleSubmit}
                disabled={!prediction || loading}
                className="w-full bg-gradient-to-r from-blue-600 to-purple-600 text-white py-4 rounded-xl font-bold text-lg hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed transition"
              >
                {loading ? '⏳ Placing...' : `🚀 Confirm (${selectedActionData?.cost} credits)`}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
